param ()

$ErrorActionPreference = "Stop"

Write-Host "=========================================================="
Write-Host "   PORTABLE GAME SERVER INSTALLATION IN WSL"
Write-Host "=========================================================="
Write-Host "This script will download the server to the default WSL environment"
Write-Host "and create shortcuts on your Desktop with custom icons."
Write-Host "If already installed, it will automatically update the repository."
Write-Host ""

# Check WSL
try {
    $wslStatus = wsl --status 2>&1
} catch {
    Write-Host "[ERROR] WSL does not seem to be installed or an error occurred." -ForegroundColor Red
    Write-Host "Make sure you have WSL2 and Docker Desktop installed before continuing."
    exit 1
}

$RepoUrl = "https://github.com/h4cKEngine/Portable-Self-Hosted-Game-Server-with-Docker.git"
$WslDir = "~/Portable-Self-Hosted-Game-Server-with-Docker"
$DesktopDir = [Environment]::GetFolderPath("Desktop")
$OneDriveDesktop = Join-Path $env:USERPROFILE "OneDrive\Desktop"

if (-not (Test-Path $DesktopDir)) {
    if (Test-Path $OneDriveDesktop) {
        $DesktopDir = $OneDriveDesktop
    }
}

$StartShortcutName = "StartMcServer.lnk"
$StartShortcutPath = Join-Path $DesktopDir $StartShortcutName
$InstallShortcutName = "InstallServer.lnk"
$InstallShortcutPath = Join-Path $DesktopDir $InstallShortcutName
$UninstallShortcutName = "UninstallServer.lnk"
$UninstallShortcutPath = Join-Path $DesktopDir $UninstallShortcutName

# AppData directory for storing persistent resources (icons, installer & launcher)
$AppDataDir = Join-Path $env:LOCALAPPDATA "PortableMcServer"
if (-not (Test-Path $AppDataDir)) {
    New-Item -ItemType Directory -Path $AppDataDir -Force | Out-Null
}

$FolderIconPath = Join-Path $AppDataDir "mc-folder.ico"
$FolderPngPath  = Join-Path $AppDataDir "mc-folder.png"
$LogoIconPath   = Join-Path $AppDataDir "mc-2d-logo.ico"
$LogoPngPath    = Join-Path $AppDataDir "mc-2d-logo.png"
$LauncherBatPath = Join-Path $AppDataDir "StartMcServer.bat"
$InstallerBatPath = Join-Path $AppDataDir "InstallServer.bat"
$UninstallerBatPath = Join-Path $AppDataDir "UninstallServer.bat"

# Embedded Base64 icons (allows standalone installer execution)
$FolderIcoBase64 = ""
$FolderPngBase64 = ""
$LogoIcoBase64   = ""
$LogoPngBase64   = ""

try {
    [System.IO.File]::WriteAllBytes($FolderIconPath, [System.Convert]::FromBase64String($FolderIcoBase64))
    [System.IO.File]::WriteAllBytes($FolderPngPath, [System.Convert]::FromBase64String($FolderPngBase64))
    [System.IO.File]::WriteAllBytes($LogoIconPath, [System.Convert]::FromBase64String($LogoIcoBase64))
    [System.IO.File]::WriteAllBytes($LogoPngPath, [System.Convert]::FromBase64String($LogoPngBase64))
} catch {
    Write-Host "[WARN] Could not extract icons to $AppDataDir" -ForegroundColor Yellow
}

# If running inside local directory on Windows, ensure utils icons exist
try {
    $LocalScriptDir = $PSScriptRoot
    if ([string]::IsNullOrEmpty($LocalScriptDir)) {
        $LocalScriptDir = (Get-Location).Path
    }
    $LocalUtilsDir = Join-Path $LocalScriptDir "utils"
    if (Test-Path $LocalUtilsDir) {
        $LocalFolderIco = Join-Path $LocalUtilsDir "img\mc-folder.ico"
        $LocalLogoIco = Join-Path $LocalUtilsDir "img\mc-2d-logo.ico"
        if (-not (Test-Path $LocalFolderIco)) {
            [System.IO.File]::WriteAllBytes($LocalFolderIco, [System.Convert]::FromBase64String($FolderIcoBase64))
        }
        if (-not (Test-Path $LocalLogoIco)) {
            [System.IO.File]::WriteAllBytes($LocalLogoIco, [System.Convert]::FromBase64String($LogoIcoBase64))
        }
    }
} catch {
    # Ignore
}

$LauncherScript = @"
@echo off
title Game Server Dashboard
echo ==========================================================
echo       STARTING GAME SERVER DASHBOARD (WSL Bridge)
echo ==========================================================
echo Project Path: $WslDir
echo Starting web container and host agent...
wsl -e bash -c "cd $WslDir && chmod +x *.sh utils/*.sh && ./utils/fix-docker-creds.sh 2>/dev/null || true; ./utils/setup-web.sh && { explorer.exe http://localhost/index.html || true; } && ./utils/host-agent.sh"
echo Dashboard closed.
pause
"@

function Update-DesktopShortcut {
    param(
        [string]$TargetBat,
        [string]$LnkPath,
        [string]$IconFile,
        [string]$Description,
        [string]$ScriptContent = $null
    )
    if ($ScriptContent) {
        $ScriptContent | Out-File -FilePath $TargetBat -Encoding ascii
    }

    $WScriptShell = New-Object -ComObject WScript.Shell
    $Shortcut = $WScriptShell.CreateShortcut($LnkPath)
    $Shortcut.TargetPath = $TargetBat
    $Shortcut.WorkingDirectory = Split-Path -Parent $TargetBat
    if (Test-Path $IconFile) {
        $Shortcut.IconLocation = "$IconFile,0"
    }
    $Shortcut.Description = $Description
    $Shortcut.Save()
}

function Setup-All-Shortcuts {
    # Save a clean copy of InstallServer.bat to AppData
    if ($ScriptFile -and (Test-Path $ScriptFile)) {
        if ($ScriptFile -ne $InstallerBatPath) {
            Copy-Item -Path $ScriptFile -Destination $InstallerBatPath -Force
        }
    }

    # Remove legacy StartMcServer.bat from Desktop if present
    $LegacyStartBat = Join-Path $DesktopDir "StartMcServer.bat"
    if (Test-Path $LegacyStartBat) {
        Remove-Item -Path $LegacyStartBat -Force -ErrorAction SilentlyContinue
    }

    # 1. Create StartMcServer.lnk with mc-2d-logo.ico
    Update-DesktopShortcut -TargetBat $LauncherBatPath -LnkPath $StartShortcutPath -IconFile $LogoIconPath -Description "Start Portable Minecraft Server" -ScriptContent $LauncherScript

    # 2. Create InstallServer.lnk with mc-folder.ico
    Update-DesktopShortcut -TargetBat $InstallerBatPath -LnkPath $InstallShortcutPath -IconFile $FolderIconPath -Description "Update or Reinstall Portable Minecraft Server"

    # 3. Create UninstallServer.lnk with mc-folder.ico
    $uninstallContent = (wsl -e bash -c "cat $WslDir/UninstallServer.bat 2>/dev/null" | Out-String).Trim()
    if ($uninstallContent) {
        $uninstallContent | Out-File -FilePath $UninstallerBatPath -Encoding ascii
        Update-DesktopShortcut -TargetBat $UninstallerBatPath -LnkPath $UninstallShortcutPath -IconFile $FolderIconPath -Description "Uninstall Portable Minecraft Server"
    }

    # Schedule removal of the original un-iconed InstallServer.bat if run from Desktop
    $DesktopCandidates = @(
        (Join-Path $DesktopDir "InstallServer.bat"),
        (Join-Path $OneDriveDesktop "InstallServer.bat"),
        $ScriptFile
    )

    foreach ($file in $DesktopCandidates) {
        if ($file -and (Test-Path $file) -and ($file -ne $InstallerBatPath)) {
            $parent = Split-Path -Parent $file
            if (($parent -eq $DesktopDir) -or ($parent -eq $OneDriveDesktop) -or ($file -eq $ScriptFile)) {
                # Launch background PowerShell process to delete the file once cmd exits
                Start-Process powershell -ArgumentList "-NoProfile -WindowStyle Hidden -Command `"Start-Sleep -Milliseconds 600; Remove-Item -LiteralPath '$file' -Force -ErrorAction SilentlyContinue`"" -WindowStyle Hidden
            }
        }
    }
}

Write-Host "[INFO] Preparing environment in WSL path: $WslDir`n"

# Check if dir exists in WSL
$dirExists = (wsl -e bash -c "[ -d $WslDir ] && echo 1 || echo 0").Trim()

if ($dirExists -eq "1") {
    Write-Host "[INFO] The directory $WslDir already exists in WSL."
    Write-Host "[INFO] Updating the project to the latest version (git pull)..."
    wsl -e bash -c "cd $WslDir && git config core.fileMode false && git pull"
    
    if ($LASTEXITCODE -ne 0) {
        Write-Host "`n[WARN] Local changes or conflicting files were detected in the project." -ForegroundColor Yellow
        $choice = Read-Host "Do you want to overwrite local code changes with the latest version from GitHub? [Y/n]"
        if ($choice -eq "" -or $choice -match "^[yY]") {
            Write-Host "[INFO] Overwriting local changes and updating to latest GitHub version..." -ForegroundColor Cyan
            wsl -e bash -c "cd $WslDir && git fetch origin main && git reset --hard origin/main"
            if ($LASTEXITCODE -ne 0) {
                Write-Host "[ERROR] Failed to update from GitHub. Please resolve the git errors manually." -ForegroundColor Red
                exit 1
            }
        } else {
            Write-Host "[INFO] Keeping local version. Skipping update." -ForegroundColor Yellow
        }
    }

    Write-Host "[INFO] Setting permissions on scripts..."
    wsl -e bash -c "cd $WslDir && chmod +x *.sh utils/*.sh 2>/dev/null || true"

    Setup-All-Shortcuts

    Write-Host "=========================================================="
    Write-Host "[INFO] Repository updated successfully." -ForegroundColor Green
    Write-Host "[INFO] Desktop shortcuts updated with custom icons!" -ForegroundColor Green
    Write-Host "=========================================================="
    Write-Host ""
    exit 0
} else {
    Write-Host "[INFO] Cloning the project from GitHub..."
    wsl -e bash -c "git clone $RepoUrl $WslDir"
    if ($LASTEXITCODE -ne 0) {
        Write-Host "[ERROR] Failed to download the repository. Please check your internet connection." -ForegroundColor Red
        exit 1
    }
    Write-Host "[INFO] Setting permissions on scripts..."
    wsl -e bash -c "cd $WslDir && git config core.fileMode false && chmod +x *.sh utils/*.sh 2>/dev/null || true"
}

Write-Host "`n[INFO] Setting up quick start shortcuts on Windows Desktop with custom icons..."
Setup-All-Shortcuts

Write-Host "`n=========================================================="
Write-Host "   INSTALLATION COMPLETED SUCCESSFULLY!" -ForegroundColor Green
Write-Host "=========================================================="
Write-Host "You will find on your Desktop:"
Write-Host " - '$StartShortcutName' (mc-2d-logo icon) to start the server"
Write-Host " - '$InstallShortcutName' (mc-folder icon) to update or reinstall"
Write-Host ""
